  `Pontuacao_IMDB` decimal(3,1) DEFAULT NULL,
  `Data_Lancamento` date DEFAULT NULL,
  `Formato_Exibicao` varchar(50) DEFAULT NULL,
  `Trilha_Sonora` varchar(255) DEFAULT NULL,
  `Indicou_ao_Oscar` enum('S','N') NOT NULL,
  `Quantidade_de_Oscars` int DEFAULT '0',
  PRIMARY KEY (`ID`)
